function canAttack(a,b){return a?.faction==='player'&&hits(a,b);}
function hits(a,b,from=a?.position){return !!a&&!!b&&!!from&&hostile(a.faction,b.faction)&&T.canAct(a)&&T.living(a).some(m=>(m.unit.weapons?.length?m.unit.weapons:[window.PROBattle.BASIC_WEAPON]).some(w=>window.PROBattle.weaponInRange(w,Math.abs(from.x-b.position.x)+Math.abs(from.y-b.position.y))));}
